---
import YearGrid from "./YearGrid.astro";
import { formatCompact } from "../lib/format";
import {
  forecastNextMillion,
  formatForecastRelative,
  formatUtcDate,
  parseUtcDate,
  type MauPoint,
} from "../lib/mau-forecast";

interface Props {
  daily: MauPoint[];
}

const { daily } = Astro.props;
const reliableHistoryStart = "2026-03-01";
const data = daily.filter(
  (point) => point.mau > 0 && point.date >= reliableHistoryStart,
);
const latest = data.at(-1);

function formatChange(current: number, previous?: number): number | null {
  if (!previous) return null;
  return ((current - previous) / previous) * 100;
}

function snapshotAtOrBefore(date: string): MauPoint | undefined {
  return data.findLast((point) => point.date <= date);
}

function daysBefore(date: string, days: number): string {
  const timestamp = new Date(`${date}T00:00:00Z`).getTime() - days * 86400_000;
  return new Date(timestamp).toISOString().slice(0, 10);
}

function daysBetween(start: string, end: string): number {
  return Math.round(
    (new Date(`${end}T00:00:00Z`).getTime() -
      new Date(`${start}T00:00:00Z`).getTime()) /
      86400_000,
  );
}

function formatDate(date: string, month: "short" | "long" = "short"): string {
  return new Date(`${date}T00:00:00Z`).toLocaleDateString("en-US", {
    month,
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  });
}

function formatMonth(date: string): string {
  return new Date(`${date}T00:00:00Z`).toLocaleDateString("en-US", {
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  });
}

function niceStep(span: number, targetTicks = 6): number {
  const roughStep = Math.max(span / targetTicks, 1);
  const magnitude = 10 ** Math.floor(Math.log10(roughStep));
  const normalized = roughStep / magnitude;
  const multiplier = normalized <= 1 ? 1 : normalized <= 2 ? 2 : normalized <= 5 ? 5 : 10;
  return multiplier * magnitude;
}

const monthEnds = [
  ...data
    .reduce((months, point) => {
      months.set(point.date.slice(0, 7), point);
      return months;
    }, new Map<string, MauPoint>())
    .values(),
];
const recentMonths = monthEnds.slice(-12);

const thirtyDayBaseline = latest
  ? snapshotAtOrBefore(daysBefore(latest.date, 30))
  : undefined;
const thirtyDayChange = latest
  ? formatChange(latest.mau, thirtyDayBaseline?.mau)
  : null;

const quattroLaunch = "2026-08-14";
const quattroBaseline = snapshotAtOrBefore(daysBefore(quattroLaunch, 1));
const quattroChange =
  latest && latest.date >= quattroLaunch
    ? formatChange(latest.mau, quattroBaseline?.mau)
    : null;

const forecast = forecastNextMillion(data);
const showForecastOnChart = Boolean(forecast?.showOnChart);
const width = 1000;
const height = 280;
const padding = { top: 28, right: showForecastOnChart ? 36 : 24, bottom: 42, left: 70 };
const chartWidth = width - padding.left - padding.right;
const chartHeight = height - padding.top - padding.bottom;
const values = [
  ...data.map((point) => point.mau),
  ...(showForecastOnChart && forecast ? [forecast.target] : []),
];
const rawMin = values.length > 0 ? Math.min(...values) : 0;
const rawMax = values.length > 0 ? Math.max(...values) : 1;
const range = Math.max(rawMax - rawMin, rawMax * 0.1, 1);
const yStep = niceStep(range);
const yMin = Math.max(0, Math.floor(rawMin / yStep) * yStep);
let yMax = Math.ceil(rawMax / yStep) * yStep;
if (yMax <= yMin) yMax = yMin + yStep;
if (showForecastOnChart && forecast && yMax <= forecast.target) {
  yMax = forecast.target + yStep;
}
const timestampForDate = (date: string) => parseUtcDate(date);
const firstTimestamp = data.length > 0 ? timestampForDate(data[0].date) : 0;
const chartEndDate = (() => {
  if (!latest) return "";
  if (!showForecastOnChart || !forecast) return latest.date;
  const historyDays = Math.max(daysBetween(data[0].date, latest.date), 1);
  const padDays = Math.max(4, Math.round(historyDays * 0.05));
  return formatUtcDate(parseUtcDate(forecast.hitDate) + padDays * 86400_000);
})();
const lastTimestamp = chartEndDate ? timestampForDate(chartEndDate) : firstTimestamp;
const xForDate = (date: string) =>
  firstTimestamp === lastTimestamp
    ? chartWidth / 2
    : ((timestampForDate(date) - firstTimestamp) /
        (lastTimestamp - firstTimestamp)) *
      chartWidth;
const yForValue = (value: number) =>
  chartHeight - ((value - yMin) / (yMax - yMin)) * chartHeight;
const mauPath = data
  .map(
    (point, index) =>
      `${index === 0 ? "M" : "L"} ${xForDate(point.date)} ${yForValue(point.mau)}`,
  )
  .join(" ");
const mauAreaPath =
  data.length > 0 && latest
    ? `${mauPath} L ${xForDate(latest.date)} ${chartHeight} L ${xForDate(data[0].date)} ${chartHeight} Z`
    : "";
const forecastPath =
  showForecastOnChart && forecast && latest
    ? `M ${xForDate(latest.date)} ${yForValue(latest.mau)} L ${xForDate(forecast.hitDate)} ${yForValue(forecast.target)}`
    : "";
const forecastAreaPath =
  showForecastOnChart && forecast && latest
    ? `M ${xForDate(latest.date)} ${yForValue(latest.mau)} L ${xForDate(forecast.hitDate)} ${yForValue(forecast.target)} L ${xForDate(forecast.hitDate)} ${chartHeight} L ${xForDate(latest.date)} ${chartHeight} Z`
    : "";
const forecastLabel =
  forecast
    ? `${forecast.targetLabel} · ${formatDate(forecast.hitDate)}`
    : "";
const forecastPillWidth = Math.max(108, forecastLabel.length * 6.7 + 18);
const forecastPoint = showForecastOnChart && forecast
  ? {
      x: xForDate(forecast.hitDate),
      y: yForValue(forecast.target),
    }
  : null;
const forecastPill =
  forecastPoint && forecast
    ? {
        x: Math.min(
          Math.max(forecastPoint.x - forecastPillWidth + 8, 4),
          chartWidth - forecastPillWidth - 4,
        ),
        y: forecastPoint.y > 30 ? forecastPoint.y - 28 : forecastPoint.y + 14,
      }
    : null;
const showQuattroLaunch =
  data.length > 0 && quattroLaunch >= data[0].date && quattroLaunch <= latest!.date;
const monthStarts = [
  ...data
    .reduce((months, point) => {
      const month = point.date.slice(0, 7);
      if (!months.has(month)) months.set(month, point);
      return months;
    }, new Map<string, MauPoint>())
                stroke="var(--border)"
                stroke-width="1"
                opacity="0.95"
              />
              <text
                x={forecastPill.x + forecastPillWidth / 2}
                y={forecastPill.y + 14}
                text-anchor="middle"
                class="fill-gray-400 text-[11px]"
              >
                {forecastLabel}
              </text>
            </g>
          )}
          {xTicks.map((point) => {
            return (
              <text x={xForDate(point.date)} y={chartHeight + 24} text-anchor="middle" class="fill-gray-500 text-xs">
                {new Date(`${point.date}T00:00:00Z`).toLocaleDateString("en-US", { month: "short", timeZone: "UTC" })}
              </text>
            );
          })}
          {showForecastOnChart && forecast && (
            <text
              x={xForDate(forecast.hitDate)}
              y={chartHeight + 24}
              text-anchor="middle"
              class="fill-amber-300/80 text-[11px]"
            >
              {new Date(`${forecast.hitDate}T00:00:00Z`).toLocaleDateString("en-US", { month: "short", day: "numeric", timeZone: "UTC" })}
            </text>
          )}
        </g>
      </svg>
    </div>
    {forecast && (
      <p class="mt-2 text-[11px] text-gray-500">
        {showForecastOnChart
          ? `Dashed gold line projects the ${forecast.paceLabel}.`
          : `On pace for ${forecast.targetLabel} around ${formatDate(forecast.hitDate)} (${formatForecastRelative(forecast.daysAway)}), from the ${forecast.paceLabel}. Too far out to plot.`}
      </p>
    )}

    {recentMonths.length > 0 && (
      <details class="monthly-history mt-5">
        <summary class="text-sm font-medium text-gray-300 mb-2">Monthly history <span class="text-gray-500">⌄</span></summary>
        <div class="hidden overflow-x-auto sm:block">
          <table class="w-full text-sm">
            <thead>
              <tr class="border-b border-dark-600 text-left text-xs text-gray-500">
                <th class="py-2 pr-4 font-medium">Month</th>
                <th class="py-2 px-4 font-medium">Snapshot date</th>
                <th class="py-2 px-4 font-medium text-right">MAU snapshot</th>
                <th class="py-2 pl-4 font-medium text-right">Change vs prior snapshot</th>
              </tr>
            </thead>
            <tbody>
              {[...recentMonths].reverse().map((point) => {
                const index = monthEnds.indexOf(point);
                const previous = index > 0 ? monthEnds[index - 1] : undefined;
                const change = formatChange(point.mau, previous?.mau);
                return (
                  <tr class="border-b border-dark-700 last:border-0">
                    <td class="py-2 pr-4 text-gray-300 whitespace-nowrap">
                      {formatMonth(point.date)}
                      {point === latest && <span class="ml-2 text-xs text-gray-500">latest</span>}
                    </td>
                    <td class="py-2 px-4 text-gray-500 whitespace-nowrap">{formatDate(point.date)}</td>
                    <td class="py-2 px-4 text-right text-gray-300" title={`Snapshot from ${point.date}`}>
                      {point.mau.toLocaleString()}
                    </td>
                    <td class={`py-2 pl-4 text-right ${change === null ? 'text-gray-500' : change >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                      {change === null ? "—" : `${change >= 0 ? "+" : ""}${change.toFixed(1)}%`}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <div class="space-y-2 sm:hidden">
          {[...recentMonths].reverse().map((point) => {
            const index = monthEnds.indexOf(point);
            const previous = index > 0 ? monthEnds[index - 1] : undefined;
            const change = formatChange(point.mau, previous?.mau);
            return (
              <div class="rounded border border-dark-600 bg-dark-700 p-3">
                <div class="flex items-start justify-between gap-3">
                  <div>
                    <div class="text-sm text-gray-300">
                      {formatMonth(point.date)}
                      {point === latest && <span class="ml-2 text-xs text-gray-500">latest</span>}
                    </div>
                    <div class="text-xs text-gray-500">As of {formatDate(point.date)}</div>
                  </div>
                  <div class="text-right">
                    <div class="font-medium text-gray-200">{point.mau.toLocaleString()}</div>
                    <div class={`text-xs ${change === null ? 'text-gray-500' : change >= 0 ? 'text-green-400' : 'text-red-400'}`}>
                      {change === null
                        ? "No prior snapshot"
                        : `${change >= 0 ? "+" : ""}${change.toFixed(1)}% vs ${formatDate(previous!.date).replace(/, \d{4}$/, "")}`}
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </details>
    )}
  </section>
)}

<style>
  .mau-forecast-dash { stroke-dasharray: 7 6; }
</style>
export type MauPoint = { date: string; mau: number };

export type MauForecast = {
  target: number;
  targetLabel: string;
  hitDate: string;
  daysAway: number;
  dailySlope: number;
  windows: number[];
  paceLabel: string;
  showOnChart: boolean;
  showInText: boolean;
};

export const PACE_WINDOWS_DAYS = [7, 30, 365] as const;
export const CHART_HORIZON_MONTHS = 16;
export const TEXT_HORIZON_YEARS = 10;

const DAY_MS = 86_400_000;

export function parseUtcDate(date: string): number {
  return Date.parse(`${date}T00:00:00Z`);
}

export function formatUtcDate(ms: number): string {
  return new Date(ms).toISOString().slice(0, 10);
}

export function addUtcMonths(date: string, months: number): string {
  const next = new Date(`${date}T00:00:00Z`);
  next.setUTCMonth(next.getUTCMonth() + months);
  return next.toISOString().slice(0, 10);
}

export function nextMillion(mau: number): number {
  return (Math.floor(Math.max(mau, 0) / 1_000_000) + 1) * 1_000_000;
}

export function formatMillionLabel(target: number): string {
  return `${target / 1_000_000}M`;
}

export function formatForecastRelative(daysAway: number): string {
  if (daysAway <= 0) return "today";
  if (daysAway === 1) return "tomorrow";
  if (daysAway < 21) return `in ${daysAway} days`;
  if (daysAway < 60) {
    const weeks = Math.max(1, Math.round(daysAway / 7));
    return weeks === 1 ? "in 1 week" : `in ${weeks} weeks`;
  }
  if (daysAway < 730) {
    const months = Math.max(1, Math.round(daysAway / 30.44));
    return months === 1 ? "in 1 month" : `in ${months} months`;
  }
  const years = daysAway / 365.25;
  const rounded = years >= 10 ? years.toFixed(0) : years.toFixed(1);
  return `in ${rounded} years`;
}

export function formatPaceLabel(windows: number[]): string {
  if (windows.length === 0) return "";
  if (windows.length === 1) return `${windows[0]}-day rate`;
  const names = windows.map((days) => `${days}-day`);
  if (names.length === 2) return `average of ${names[0]} and ${names[1]} rates`;
  return `average of ${names.slice(0, -1).join(", ")}, and ${names.at(-1)} rates`;
}

function snapshotAtOrBefore(
  series: MauPoint[],
  date: string,
): MauPoint | undefined {
  return series.findLast((point) => point.date <= date);
}

function daysBetween(start: string, end: string): number {
  return (parseUtcDate(end) - parseUtcDate(start)) / DAY_MS;
}

function windowRate(
  series: MauPoint[],
  latest: MauPoint,
  windowDays: number,
): number | null {
  const targetDate = formatUtcDate(
    parseUtcDate(latest.date) - windowDays * DAY_MS,
  );
  const baseline = snapshotAtOrBefore(series, targetDate) ?? series[0];
  if (!baseline || baseline.date >= latest.date) return null;

  const spanDays = daysBetween(baseline.date, latest.date);
  if (spanDays < 2 || spanDays < windowDays * 0.5) return null;
  return (latest.mau - baseline.mau) / spanDays;
}

export function blendedDailyPace(points: MauPoint[]): {
  slope: number;
  windows: number[];
} | null {
  const series = points.filter((point) => point.mau > 0);
  const latest = series.at(-1);
  if (!latest) return null;

  const rates: number[] = [];
  const windows: number[] = [];
  for (const windowDays of PACE_WINDOWS_DAYS) {
    const rate = windowRate(series, latest, windowDays);
    if (rate === null) continue;
    rates.push(rate);
    windows.push(windowDays);
  }
  if (rates.length === 0) return null;

  const slope = rates.reduce((sum, rate) => sum + rate, 0) / rates.length;
  return { slope, windows };
}

export function forecastNextMillion(points: MauPoint[]): MauForecast | null {
  const series = points.filter((point) => point.mau > 0);
  const latest = series.at(-1);
  if (!latest) return null;

  const pace = blendedDailyPace(series);
  if (pace === null || pace.slope <= 0) return null;

  const target = nextMillion(latest.mau);
  const remaining = target - latest.mau;
  if (remaining <= 0) return null;

  const rawDays = remaining / pace.slope;
  if (!Number.isFinite(rawDays) || rawDays <= 0) return null;

  const hitMs = parseUtcDate(latest.date) + rawDays * DAY_MS;
  const hitDate = formatUtcDate(hitMs);
  const daysAway = Math.max(
    0,
    Math.round((parseUtcDate(hitDate) - parseUtcDate(latest.date)) / DAY_MS),
  );
  const chartDeadline = addUtcMonths(latest.date, CHART_HORIZON_MONTHS);
  const textDeadline = addUtcMonths(latest.date, TEXT_HORIZON_YEARS * 12);

  if (hitDate > textDeadline) return null;

  return {
    target,
    targetLabel: formatMillionLabel(target),
    hitDate,
    daysAway,
    dailySlope: pace.slope,
    windows: pace.windows,
    paceLabel: formatPaceLabel(pace.windows),
    showOnChart: hitDate <= chartDeadline,
    showInText: true,
  };
}
/// <reference types="node" />

import assert from "node:assert/strict";
import test from "node:test";
import {
  blendedDailyPace,
  forecastNextMillion,
  formatForecastRelative,
  formatMillionLabel,
  formatPaceLabel,
  nextMillion,
} from "./mau-forecast";

function series(
  start: string,
  values: number[],
  stepDays = 1,
): Array<{ date: string; mau: number }> {
  const origin = Date.parse(`${start}T00:00:00Z`);
  return values.map((mau, index) => ({
    date: new Date(origin + index * stepDays * 86_400_000)
      .toISOString()
      .slice(0, 10),
    mau,
  }));
}

test("next million is the first million above current MAU", () => {
  assert.equal(nextMillion(755_509), 1_000_000);
  assert.equal(nextMillion(999_999), 1_000_000);
  assert.equal(nextMillion(1_000_000), 2_000_000);
  assert.equal(nextMillion(1_500_000), 2_000_000);
  assert.equal(nextMillion(2_000_001), 3_000_000);
});

test("million labels stay compact", () => {
  assert.equal(formatMillionLabel(1_000_000), "1M");
  assert.equal(formatMillionLabel(2_000_000), "2M");
});

test("relative copy covers days, weeks, months, and years", () => {
  assert.equal(formatForecastRelative(0), "today");
  assert.equal(formatForecastRelative(1), "tomorrow");
  assert.equal(formatForecastRelative(16), "in 16 days");
  assert.equal(formatForecastRelative(21), "in 3 weeks");
  assert.equal(formatForecastRelative(90), "in 3 months");
  assert.equal(formatForecastRelative(800), "in 2.2 years");
});

test("pace labels name the windows that contributed", () => {
  assert.equal(formatPaceLabel([7]), "7-day rate");
  assert.equal(formatPaceLabel([7, 30]), "average of 7-day and 30-day rates");
  assert.equal(
    formatPaceLabel([7, 30, 365]),
    "average of 7-day, 30-day, and 365-day rates",
  );
});

test("blends 7-day, 30-day, and 365-day endpoint rates equally", () => {
  const points = [
    { date: "2025-12-31", mau: 335_000 },
    { date: "2026-12-01", mau: 400_000 },
    { date: "2026-12-24", mau: 560_000 },
    { date: "2026-12-31", mau: 700_000 },
  ];
  const pace = blendedDailyPace(points);
  assert.ok(pace);
  assert.deepEqual(pace.windows, [7, 30, 365]);
  assert.ok(Math.abs(pace.slope - (20_000 + 10_000 + 1_000) / 3) < 1e-6);
});

test("constant recent climb still hits 1M on that pace", () => {
  const points = series(
    "2026-08-17",
    Array.from({ length: 21 }, (_, i) => 460_000 + i * 14_000),
  );
  const forecast = forecastNextMillion(points);
  assert.ok(forecast);
  assert.equal(forecast.target, 1_000_000);
  assert.equal(forecast.targetLabel, "1M");
  assert.equal(forecast.hitDate, "2026-09-24");
  assert.equal(forecast.daysAway, 18);
  assert.deepEqual(forecast.windows, [7, 30]);
  assert.equal(forecast.showOnChart, true);
  assert.equal(forecast.showInText, true);
  assert.ok(Math.abs(forecast.dailySlope - 14_000) < 1e-6);
});

test("after 1M the same slope aims at 2M", () => {
  const points = series(
    "2026-10-01",
    Array.from({ length: 21 }, (_, i) => 1_050_000 + i * 10_000),
  );
  const forecast = forecastNextMillion(points);
  assert.ok(forecast);
  assert.equal(forecast.target, 2_000_000);
  assert.equal(forecast.targetLabel, "2M");
  assert.equal(forecast.showOnChart, true);
});

test("hides the chart line after 16 months but keeps page copy", () => {
  const points = series(
    "2026-01-01",
    Array.from({ length: 21 }, (_, i) => 100_000 + i * 1_000),
  );
  const forecast = forecastNextMillion(points);
  assert.ok(forecast);
  assert.equal(forecast.showOnChart, false);
  assert.equal(forecast.showInText, true);
  assert.ok(forecast.daysAway > 16 * 30);
});

test("omits forecasts more than 10 years out", () => {
  const points = series(
    "2026-01-01",
    Array.from({ length: 21 }, (_, i) => 100_000 + i * 20),
  );
  assert.equal(forecastNextMillion(points), null);
});

test("omits a forecast when MAU is not increasing", () => {
  const points = series(
    "2026-08-01",
    Array.from({ length: 21 }, (_, i) => 800_000 - i * 1_000),
  );
  assert.equal(forecastNextMillion(points), null);
});

test("long-run rate pulls a short spike later than a 7-day fit alone", () => {
  const slow = series(
    "2026-01-01",
    Array.from({ length: 359 }, (_, i) => 300_000 + i * 500),
  );
  const latestSlow = slow.at(-1)!;
  const fast = series(
    latestSlow.date,
    Array.from({ length: 8 }, (_, i) => latestSlow.mau + i * 20_000),
  );
  const points = [...slow.slice(0, -1), ...fast];
  const forecast = forecastNextMillion(points);
  assert.ok(forecast);
  assert.deepEqual(forecast.windows, [7, 30, 365]);

  const sevenDayOnly = (fast.at(-1)!.mau - fast[0]!.mau) / 7;
  assert.ok(forecast.dailySlope < sevenDayOnly);
  assert.ok(forecast.hitDate >= "2027-02-01");
});

test("projects the post-Quattro climb in late September 2026", () => {
  const points = [
    ["2026-08-17", 481_024],
    ["2026-08-18", 497_974],
    ["2026-08-19", 508_684],
    ["2026-08-20", 518_085],
    ["2026-08-21", 528_046],
    ["2026-08-22", 536_235],
    ["2026-08-23", 544_070],
    ["2026-08-24", 568_065],
    ["2026-08-25", 593_168],
    ["2026-08-26", 609_492],
    ["2026-08-27", 626_301],
    ["2026-08-28", 639_563],
    ["2026-08-29", 646_457],
    ["2026-08-30", 652_422],
    ["2026-08-31", 676_917],
    ["2026-09-01", 701_828],
    ["2026-09-02", 720_069],
    ["2026-09-03", 734_217],
    ["2026-09-04", 747_358],
    ["2026-09-05", 752_423],
    ["2026-09-06", 755_509],
  ].map(([date, mau]) => ({ date: String(date), mau: Number(mau) }));
  const forecast = forecastNextMillion(points);
  assert.ok(forecast);
  assert.equal(forecast.targetLabel, "1M");
  assert.equal(forecast.showOnChart, true);
  assert.ok(forecast.hitDate >= "2026-09-20");
  assert.ok(forecast.hitDate <= "2026-09-26");
});

test("needs enough recent points to fit", () => {
  assert.equal(
    forecastNextMillion([
      { date: "2026-09-01", mau: 700_000 },
      { date: "2026-09-02", mau: 720_000 },
    ]),
    null,
  );
});

