  assert.equal(forecast.showOnChart, true);
  assert.equal(forecast.showInText, true);
  assert.ok(Math.abs(forecast.dailySlope - 14_000) < 1e-6);
});

test("after 1M the same slope aims at 2M", () => {
  const points = series(
